<!-- ========== WELCOME POPUP ========== -->
  <div id="welcomePopup" style="display:none; position:fixed; inset:0; z-index:9999; background:rgba(7,8,13,0.85); backdrop-filter:blur(6px); align-items:center; justify-content:center; padding:1rem;">
    <div style="background:linear-gradient(160deg,#101320,#0b0e18); border:1px solid rgba(232,185,35,0.4); border-radius:14px; padding:2.5rem 2rem; max-width:420px; width:100%; text-align:center; box-shadow:0 30px 80px -20px rgba(0,0,0,0.95), 0 0 60px rgba(232,185,35,0.15);">
      <i class="bi bi-stars" style="color:#e8b923; font-size:2.5rem; filter:drop-shadow(0 0 15px rgba(232,185,35,0.5));"></i>
      <h2 style="font-family:'Cinzel',serif; font-size:1.9rem; color:#fff; margin:1rem 0 0.5rem;">Welcome!</h2>
      <h3 id="popupUsername" style="font-family:'Cinzel',serif; font-size:1.4rem; color:#e8b923; margin-bottom:1.25rem;">Hero</h3>
      <p style="color:#8a93a8; font-size:0.95rem; margin-bottom:2rem; line-height:1.6;">Your legend begins now.</p>
      <button id="closeWelcome" type="button" style="background:linear-gradient(135deg,#e8b923,#ff6b35); color:#14100a; font-weight:700; text-transform:uppercase; letter-spacing:0.08em; font-size:0.9rem; padding:0.85rem 2rem; border-radius:8px; border:none; cursor:pointer; width:100%; font-family:'Inter',sans-serif; box-shadow:0 6px 24px rgba(232,185,35,0.25); transition:all 0.25s ease;">
        Enter the Realm
      </button>
    </div>
  </div>